def get_localized_text(key: str, lang_code: str = "en", **kwargs) -> str:
    """Return localized fallback string for the specified key and language code."""
    translations = LOCALIZED_TEXTS.get(key, {})
    template = translations.get(lang_code) or translations.get("en", "")
    if kwargs:
        return template.format(**kwargs)
    return template
